-- RAT SKY - All-In-One iPad/Delta V1
-- Six .tex faces embedded directly in this file.

local write=writefile
local custom=getcustomasset or getsynasset
if not (write and custom) then
    warn("[RAT SKY] writefile/getcustomasset missing")
    return
end

local B='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function b64decode(data)
    data=data:gsub('[^'..B..'=]','')
    return (data:gsub('.',function(x)
        if x=='=' then return '' end
        local r,f='',B:find(x,1,true)-1
        for i=6,1,-1 do
            r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0')
        end
        return r
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
        if #x~=8 then return '' end
        local c=0
        for i=1,8 do
            c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0)
        end
        return string.char(c)
    end))
end

local DATA={
bk=[[]],
dn=[[]],
ft=[[]],
lf=[[]],
rt=[[]],
up=[[]],
}
local props={
    bk="SkyboxBk", dn="SkyboxDn", ft="SkyboxFt",
    lf="SkyboxLf", rt="SkyboxRt", up="SkyboxUp"
}
local assets={}

for _,f in ipairs({"bk","dn","ft","lf","rt","up"}) do
    local ok,res=pcall(function()
        local fn="rat_sky_"..f..".tex"
        write(fn,b64decode(DATA[f]))
        return custom(fn)
    end)
    if ok then
        assets[f]=res
    else
        warn("[RAT SKY] "..f.." failed: "..tostring(res))
    end
    task.wait(.08)
end

local Lighting=game:GetService("Lighting")

local function applySky()
    local s=Lighting:FindFirstChild("RatSky")
    if not s or not s:IsA("Sky") then
        s=Lighting:FindFirstChildOfClass("Sky")
    end
    if not s then
        s=Instance.new("Sky")
        s.Name="RatSky"
        s.Parent=Lighting
    else
        s.Name="RatSky"
    end

    for f,a in pairs(assets) do
        if a then
            pcall(function()
                s[props[f]]=a
            end)
        end
    end
end

applySky()

Lighting.ChildAdded:Connect(function(o)
    if o:IsA("Sky") then
        task.delay(.2,applySky)
    end
end)

task.spawn(function()
    for _,t in ipairs({.5,1.5,3,6,10}) do
        task.wait(t)
        applySky()
    end
end)

pcall(function()
    game:GetService("StarterGui"):SetCore("SendNotification",{
        Title="Rat Sky",
        Text="Rat sky loaded",
        Duration=6
    })
end)

print("[RAT SKY] loaded")
